using System;using System.Linq;using System.IO;using System.Xml;using System.Threading;using BeamScheduleFormatter;
class WindRecoveryTests {
 static int checks;static void Check(bool x,string text){if(!x)throw new Exception(text);checks++;}static void Near(double x,double y,string text){Check(Math.Abs(x-y)<1e-7,text);}static WindTerrain Flat(int cover){var t=new WindTerrain{Lat=14.5995,Lon=120.9842,Radius=3200,Acquired=DateTime.UtcNow};foreach(var ray in t.Rays)for(int n=0;n<=32;n++)ray.Add(new WindSample{Lat=t.Lat,Lon=t.Lon,D=n*100,Z=10,Cover=cover});foreach(var cross in t.Cross)for(int n=-32;n<=32;n++)cross.Add(new WindSample{Lat=t.Lat,Lon=t.Lon,D=n*100,Z=10});return t;}
 static int Main(string[] args){try{if(args.Contains("live")){var client=new WindTerrainClient("/workspace/cache/wind");var data=client.Load(14.5995,120.9842,3200,CancellationToken.None);var doc=new XmlDocument();var root=doc.CreateElement("WindExample");doc.AppendChild(root);WindTerrainXml.Write(root,data);doc.Save("/workspace/DTCE-Tool-Kit/test-results/Wind-Manila-Example.xml");File.WriteAllText("/workspace/DTCE-Tool-Kit/test-results/Wind-Manila-Example.txt",WindReport.Build(data.Lat,data.Lon,"II",10,.85,data,false));Console.WriteLine("LIVE: "+data.Rays.Sum(r=>r.Count)+" surface samples; all8 directions assessed; Manila TEST location only.");return 0;}
 var a=new WindNode{X=0,Y=0,V=240};var b=new WindNode{X=10,Y=0,V=260};var c=new WindNode{X=0,Y=10,V=280};var w=WindTin.Barycentric(a,b,c,2,3);Near(w[0],.5,"First barycentric weight");Near(w[1],.2,"Second weight");Near(w[2],.3,"Third weight");Near(w[0]*a.V+w[1]*b.V+w[2]*c.V,256,"Interpolated wind retains full precision");foreach(var p in new[]{new[]{14.5995,120.9842},new[]{18.356,121.64},new[]{7.07,125.61}}){var high=WindTin.At(p[0],p[1],"I");var mid=WindTin.At(p[0],p[1],"II");var low=WindTin.At(p[0],p[1],"III-V");Check(high.V>=mid.V&&mid.V>=low.V,"NSCP occupancy map ordering");Check(high.Map==29&&mid.Map==28&&low.Map==27,"Correct workbook image association");Near(mid.Weights.Sum(),1,"TIN weights sum to1");Check(!mid.Coastal,"Control point lies in TIN hull");}Near(WindAssessment.BFetch(9),457.2,"Low B fetch");Near(WindAssessment.BFetch(10),792.48,"High B fetch");Near(WindAssessment.BFetch(50),1000,"20h fetch governs");foreach(int cover in new[]{50,30,80,0}){var d=WindAssessment.Calculate(Flat(cover),10,300,.85);Check(d.Count==8,"Eight directions");Check(d.All(r=>r.Exposure==(cover==50?"B":cover==80?"D":cover==0?"Unresolved":"C")),"Directional exposure screening");if(cover==0)Check(d.All(r=>double.IsNaN(r.Kzt)&&double.IsNaN(r.Qz)),"Missing data never silently defaults to C/Kzt1");else Check(d.All(r=>r.Kzt==1&&r.Qz>0),"Low-relief Kzt/qz");}var k=WindAssessment.Factors(20,80,0,10,"C","Ridge");Near(k[0],1.45*.25,"Ridge K1");Near(k[1],1,"Crest K2");Near(k[2],Math.Exp(-3*10.0/80),"Ridge K3 decay");Near(k[3],Math.Pow(1+k[0]*k[1]*k[2],2),"Kzt equation");var steep=WindAssessment.Factors(100,50,100,10,"D","Hill");Near(steep[0],1.15*.5,"Steep slope cap");Near(steep[1],1-100.0/300,"Steep effective Lh");var doc2=new XmlDocument();var root2=doc2.CreateElement("Test");doc2.AppendChild(root2);WindTerrainXml.Write(root2,Flat(50));var restored=WindTerrainXml.Read(root2);Check(restored.Rays.Length==24&&restored.Cross.Length==8&&restored.Rays[0].Count==33,"Offline terrain roundtrip");string report=WindReport.Build(restored.Lat,restored.Lon,"II",10,.85,restored,false);Check(report.Contains("PRELIMINARY")&&report.Contains("VELOCITY PRESSURE")&&report.Contains("barycentric"),"Reports preserve limitations and derivation");Check(ProgramAccess.Allows(128,128)&&!ProgramAccess.Allows(119,128)&&!ProgramAccess.Allows(128,32),"Independent wind program permission");Console.WriteLine("PASS: "+checks+" recovered wind interpolation/terrain/exposure/state checks.");return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}
